mapper.sql:
(
SELECT ai.id assetId, ai.uid assetUid, ai.name, ai.clinical_dept_uid clinicalDeptUid, ai.clinical_dept_name clinicalDeptName, ai.qr_code qrCode, ai.depart_num departNum, ai.function_type functionType, ai.financing_num financingNum, ai.status assetStatus, ai.location_name locationName, ai.institution_uid institutionUid, ai.hospital_uid hospitalUid, ai.site_uid siteUid, ai.purchase_price purchasePrice, ai.purchase_date purchaseDate, ai.comments assetComments, ai.make_short_name makerShortName, ai.asset_owner_name repairOwner, u.name inventoryName, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN iod.comment WHEN ii.comment IS NOT NULL THEN ii.comment ELSE iod.comment end, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN '' WHEN ii.is_solved = TRUE THEN '是' WHEN ii.is_solved = FALSE THEN '否' ELSE '' END isSolved, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN '' WHEN ii.id IS NOT NULL THEN (select string_agg(icl.item, ', ') from inventory_check_list icl left join inventory_issue_detail isd on icl.id = isd.inventory_check_list_id where isd.inventory_issue_id = ii.id group by isd.inventory_issue_id) ELSE '' END inventoryCheckListItems, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN iod.last_modified_by WHEN ii.last_modified_by IS NOT NULL THEN ii.last_modified_by ELSE iod.last_modified_by END lastModifiedBy, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN iod.last_modified_date WHEN ii.last_modified_date IS NOT NULL THEN ii.last_modified_date ELSE iod.last_modified_date END lastModifiedDate, CASE WHEN iod.last_modified_date > ii.last_modified_date THEN iod.status WHEN ii.id IS NOT NULL THEN 3 WHEN iod.status IS NULL THEN 4 ELSE iod.status END status FROM asset_info ai LEFT JOIN inventory_issue ii ON ai.id = ii.asset_id AND ii.is_last is true LEFT JOIN inventory_order_detail iod ON ai.id = iod.asset_id AND iod.is_last is true left join user_account u on u.login_name=iod.last_modified_by WHERE ai.is_checked = TRUE AND ai.is_deleted = FALSE AND ai.is_valid = TRUE AND ai.tenant_uid = #{tenantUid}
AND ai.asset_type IN
#{item}
AND ( ai.institution_uid IN
#{item}
OR ai.hospital_uid IN
#{item}
OR ai.site_uid IN
#{item}
OR ai.clinical_dept_uid IN
#{item}
OR ai.asset_dept_uid IN
#{item}
)
) t

( SELECT NULL AS assetId, NULL AS name,org_name clinicalDeptName,qr_code qrCode,NULL departNum,NULL functionType,NULL financingNum,NULL assetStatus,NULL locationName,comment,NULL isSolved,NULL inventoryCheckListItems,last_modified_by lastModifiedBy,last_modified_date lastModifiedDate,status FROM inventory_order_detail iod WHERE status = 2
AND iod.tenant_uid = #{tenantUid}
UNION ALL SELECT ai.id assetId,ai.name,ai.clinical_dept_name clinicalDeptName,ai.qr_code qrCode,ai.depart_num departNum,ai.function_type functionType,ai.financing_num financingNum,ai.status assetStatus,ai.location_name locationName,iod.comment,CASE WHEN iod.is_solved=true THEN '是' ELSE '否' END isSolved,(select array_to_string(array_agg(icl.item), ', ') from inventory_check_list icl left join inventory_issue_detail isd on icl.id = isd.inventory_check_list_id where isd.inventory_issue_id = iod.id group by isd.inventory_issue_id) inventoryCheckListItems,iod.last_modified_by lastModifiedBy,iod.last_modified_date lastModifiedDate,3 FROM inventory_issue iod LEFT JOIN asset_info ai ON iod.asset_id = ai.id
UNION ALL SELECT ai.id assetId,ai.name,ai.clinical_dept_name clinicalDeptName,ai.qr_code qrCode,ai.depart_num departNum,ai.function_type functionType,ai.financing_num financingNum,ai.status assetStatus,ai.location_name locationName,iod.comment,NULL isSolved,NULL inventoryCheckListItems,iod.last_modified_by lastModifiedBy,iod.last_modified_date lastModifiedDate,iod.status FROM inventory_order_detail iod LEFT JOIN asset_info ai ON ai.id = iod.asset_id
AND ai.id NOT IN
#{item}
UNION ALL SELECT ai.id assetId,ai.name,ai.clinical_dept_name clinicalDeptName,ai.qr_code qrCode,ai.depart_num departNum,ai.function_type functionType,ai.financing_num financingNum,ai.status assetStatus,ai.location_name locationName,NULL,NULL isSolved,NULL inventoryCheckListItems,NULL lastModifiedBy,NULL lastModifiedDate,4 FROM asset_info ai
AND ai.id NOT IN
#{item}
) t

WHERE ai.is_checked = TRUE AND ai.is_deleted = FALSE AND ai.is_valid = TRUE AND ai.tenant_uid = #{tenantUid}

    AND (
        ai.institution_uid IN

            #{item}

        OR ai.hospital_uid IN

            #{item}

